<script setup lang="ts">
import DataExportPanel from './components/DataExportPanel.vue'
import DataDeletionPanel from './components/DataDeletionPanel.vue'
import NotificationPanel from './components/NotificationPanel.vue'
import WeatherCard from './components/WeatherCard.vue'
import CoachChat from './components/CoachChat.vue'
import AssessmentPanel from './components/AssessmentPanel.vue'
import CyclePanel from './components/CyclePanel.vue'
import TrainingWeek from './components/TrainingWeek.vue'
import FeedbackHistory from './components/FeedbackHistory.vue'
import PlanPanel from './components/PlanPanel.vue'
import WorkoutMetrics from './components/WorkoutMetrics.vue'
import ImportRecognition from './components/ImportRecognition.vue'
import HeroArtwork from './components/HeroArtwork.vue'
import { computed, nextTick, onMounted, onUnmounted, reactive, ref, watch } from 'vue'
import { api, json, setCsrf, ApiError, type User, type Profile, type Workout, type Checkin, type Day, type Draft, type AIUsage, type StrengthWorkout, type PlanState } from './api'
const navs=[['today','今日概览','◫'],['calendar','训练日历','▦'],['records','训练记录','↗'],['coach','AI 教练','✧'],['settings','个人设置','☷']]
const view=ref('today'),ready=ref(false),user=ref<User|null>(null),initialized=ref(false),setupAllowed=ref(true),busy=ref(false),error=ref(''),toastText=ref('')
const auth=reactive({username:'',password:''})
const profile=reactive<Profile>({display_name:'跑者',age:null,sex:'unspecified',running_months:null,runs_per_week:3,city:'',preferred_time:'20:00',timezone:'Asia/Shanghai',goal_date:null,goal_duration_seconds:null,health_notes:'',doctor_restrictions:'',running_permission:'unknown',medical_review_date:null,strength_experience:'unknown',strength_equipment:[],strength_max_minutes:null,band_resistance:'',familiar_exercises:[],same_day_strength:false})
const refreshToken=ref(0),strengthWorkouts=ref<StrengthWorkout[]>([]),planState=ref<PlanState|null>(null)
const aiUsage=ref<AIUsage|null>(null)
const goalMinutes=ref<number|null>(null),workouts=ref<Workout[]>([]),checkins=ref<Checkin[]>([]),drafts=ref<Draft[]>([]),days=ref<Day[]>([])
const dialog=ref<''|'workout'|'checkin'|'schedule'|'draft'>(''),modalError=ref(''),selectedDraft=ref<Draft|null>(null),draftSaved=ref(false)
const inputFile=ref<HTMLInputElement|null>(null),modalElement=ref<HTMLElement|null>(null),dateNow=ref(new Date())
let lastFocus:HTMLElement|null=null,timer:ReturnType<typeof setTimeout>|undefined
const today=computed(()=>new Intl.DateTimeFormat('en-CA',{timeZone:profile.timezone,year:'numeric',month:'2-digit',day:'2-digit'}).format(dateNow.value))
function localDate(date:Date){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`}
const weekOffset=ref(0)
const week=computed(()=>{const now=new Date(today.value+'T12:00:00');now.setDate(now.getDate()-((now.getDay()+6)%7)+weekOffset.value*7);return Array.from({length:7},(_,i)=>{const d=new Date(now);d.setDate(d.getDate()+i);const date=localDate(d);return {date,day:d.getDate(),label:['一','二','三','四','五','六','日'][i],records:workouts.value.filter(w=>w.date===date),strength:strengthWorkouts.value.filter(w=>w.date===date),planned:planState.value?.plan?.sessions.filter(s=>s.date===date)||[],availability:days.value.find(a=>a.date===date)}})})
const thisWeek=computed(()=>{const a=new Date(today.value+'T12:00:00');a.setDate(a.getDate()-((a.getDay()+6)%7));const start=localDate(a);a.setDate(a.getDate()+6);return workouts.value.filter(w=>w.date>=start&&w.date<=localDate(a))})
const weekStrength=computed(()=>strengthWorkouts.value.filter(s=>s.date>=week.value[0]!.date&&s.date<=week.value[6]!.date))
const latest=computed(()=>workouts.value[0]),latestCheckin=computed(()=>checkins.value[0]),weekKm=computed(()=>thisWeek.value.reduce((sum,w)=>sum+w.distance_m,0)/1000)
const healthAttention=computed(()=>Boolean(profile.health_notes || profile.doctor_restrictions || strengthWorkouts.value.some(s=>s.date>=week.value[0]!.date&&s.pain_notes) || latestCheckin.value?.pain_location || (latestCheckin.value?.pain_level??0)>0 || (latestCheckin.value?.soreness_level??0)>0 || latestCheckin.value?.function_affected || latestCheckin.value?.illness_notes || latest.value?.pain_notes))
const daysToGoal=computed(()=>profile.goal_date?Math.ceil((Date.parse(profile.goal_date+'T00:00:00Z')-Date.parse(today.value+'T00:00:00Z'))/86400000):null)
const goalLabel=computed(()=>profile.goal_duration_seconds?`${Math.floor(profile.goal_duration_seconds/3600)}:${String(Math.floor(profile.goal_duration_seconds%3600/60)).padStart(2,'0')}`:'—')
function duration(n:number){return `${Math.floor(n/3600)}:${String(Math.floor(n%3600/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`}
function pace(n:number){return `${Math.floor(n/60)}′${String(n%60).padStart(2,'0')}″`}
function sportLabel(s:string){return ({road_run:'户外跑',trail_run:'越野跑',treadmill:'跑步机'} as Record<string,string>)[s]||s}
function notify(message:string){toastText.value=message;clearTimeout(timer);timer=setTimeout(()=>toastText.value='',3500)}
async function load(){const [p,w,c,a,d,u,s,ps]=await Promise.all([api<Profile>('/profile'),api<Workout[]>('/workouts'),api<Checkin[]>('/checkins'),api<{days:Day[]}>('/availability'),api<Draft[]>('/imports'),api<AIUsage>('/ai/usage'),Promise.resolve([] as StrengthWorkout[]),api<PlanState>('/plans/current')]);strengthWorkouts.value=s;planState.value=ps;aiUsage.value=u;Object.assign(profile,p);goalMinutes.value=p.goal_duration_seconds?p.goal_duration_seconds/60:null;workouts.value=w;checkins.value=c;days.value=a.days;drafts.value=d;refreshToken.value++}
async function initialize(){try{const status=await api<{initialized:boolean;setup_allowed:boolean}>('/auth/status');initialized.value=status.initialized;setupAllowed.value=status.setup_allowed;try{user.value=await api<User>('/auth/me');setCsrf(user.value.csrf_token);await load()}catch(e){if(!(e instanceof ApiError&&e.status===401))throw e}}catch(e){error.value=(e as Error).message}finally{ready.value=true}}
async function authenticate(){busy.value=true;error.value='';try{user.value=await api<User>(initialized.value?'/auth/login':'/auth/setup',json('POST',auth));setCsrf(user.value.csrf_token);auth.password='';initialized.value=true;await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function logout(){try{await api('/auth/logout',{method:'POST'});user.value=null;setCsrf('');workouts.value=[];strengthWorkouts.value=[];planState.value=null;checkins.value=[];drafts.value=[];notify('已退出登录')}catch(e){error.value=(e as Error).message}}
function changeView(id:string){view.value=id;if(id==='today')weekOffset.value=0;error.value='';window.scrollTo(0,0)}
const workoutForm=reactive({date:'',started_time:'',sport:'road_run',session_context:'unknown',title:'户外跑步',distance_km:null as number|null,duration:'',avg_heart_rate:null as number|null,max_heart_rate:null as number|null,ascent_m:null as number|null,effort:null as number|null,pain_notes:'',notes:''})
const workoutRequiredLabels={date:'运动日期',sport:'运动类型',title:'训练名称',distance_km:'实际距离',duration:'运动时间'}
function workoutMissing(field:keyof typeof workoutRequiredLabels){const value=workoutForm[field];return value===null||value===undefined||String(value).trim()===''}
const missingWorkoutFields=computed(()=>(Object.keys(workoutRequiredLabels) as (keyof typeof workoutRequiredLabels)[]).filter(workoutMissing).map(field=>workoutRequiredLabels[field]))
const feedbackClock=ref(''),feedbackTraining=ref('')
const feedbackOptions=computed(()=>[...workouts.value.map(r=>({key:`run:${r.id}`,type:'run',id:r.id,date:r.date,title:r.title})),...([] as {key:string;type:string;id:string;date:string;title:string}[])].sort((a,b)=>b.date.localeCompare(a.date)))
const checkinForm=reactive({feedback_phase:'unknown',date:'',training_readiness:'unknown',soreness_level:null as number|null,soreness_location:'',soreness_timing:'unknown',soreness_trend:'unknown',soreness_tolerability:'unknown',function_affected:null as boolean|null,illness_notes:'',fatigue:2,sleep_hours:null as number|null,pain_level:null as number|null,pain_location:'',pain_timing:'none',notes:''})
const scheduleForm=ref<Day[]>([])
function resetWorkout(){Object.assign(workoutForm,{date:today.value,started_time:'',sport:'road_run',session_context:'unknown',title:'户外跑步',distance_km:null,duration:'',avg_heart_rate:null,max_heart_rate:null,ascent_m:null,effort:null,pain_notes:'',notes:''})}
function openDialog(type:typeof dialog.value){lastFocus=document.activeElement as HTMLElement;modalError.value='';if(type==='workout')resetWorkout();if(type==='checkin'){feedbackClock.value='';feedbackTraining.value='';Object.assign(checkinForm,{date:today.value,training_readiness:'unknown',soreness_level:null,soreness_location:'',soreness_timing:'unknown',soreness_trend:'unknown',soreness_tolerability:'unknown',function_affected:null,illness_notes:'',fatigue:2,sleep_hours:null,pain_level:null,pain_location:'',pain_timing:'none',notes:'',feedback_phase:'unknown'});}if(type==='schedule')scheduleForm.value=week.value.map(w=>({...w.availability||{date:w.date,available:false,duration_minutes:60}}));dialog.value=type;nextTick(()=>modalElement.value?.querySelector<HTMLElement>('button,input')?.focus())}
function closeDialog(){if(busy.value)return;dialog.value='';lastFocus?.focus()}
function parseDuration(s:string){const parts=s.split(':').map(Number);if(!/^\d{1,3}:\d{2}(:\d{2})?$/.test(s)||parts.slice(1).some(n=>n>59))throw new Error('运动时间请填写 HH:MM:SS 或 MM:SS');return parts.length===3?parts[0]*3600+parts[1]*60+parts[2]:parts[0]*60+parts[1]}
function optionalNumber(v:unknown){return v===null||v===undefined||v===''?null:Number(v)}
function workoutPayload(){if(!workoutForm.distance_km || workoutForm.distance_km<=0)throw new Error('请填写实际距离');return {date:workoutForm.date,started_time:workoutForm.started_time||null,sport:workoutForm.sport,session_context:workoutForm.session_context,title:workoutForm.title,distance_m:Math.round(workoutForm.distance_km*1000),duration_seconds:parseDuration(workoutForm.duration),avg_heart_rate:optionalNumber(workoutForm.avg_heart_rate),max_heart_rate:optionalNumber(workoutForm.max_heart_rate),ascent_m:optionalNumber(workoutForm.ascent_m),effort:optionalNumber(workoutForm.effort),pain_notes:workoutForm.pain_notes,notes:workoutForm.notes}}
async function saveWorkout(){busy.value=true;modalError.value='';try{await api('/workouts',json('POST',workoutPayload()));await load();dialog.value='';notify('训练已保存')}catch(e){modalError.value=(e as Error).message}finally{busy.value=false}}
function trainingFeedback(type:'run'|'strength',id:string){openDialog('checkin');feedbackTraining.value=`${type}:${id}`}
async function saveCheckin(){busy.value=true;modalError.value='';try{await api('/checkins',json('POST',{...checkinForm,observed_time:feedbackClock.value||null,related_training_type:feedbackTraining.value?feedbackTraining.value.split(':')[0]:null,related_training_id:feedbackTraining.value?feedbackTraining.value.split(':')[1]:null,soreness_level:optionalNumber(checkinForm.soreness_level),sleep_hours:optionalNumber(checkinForm.sleep_hours),pain_level:optionalNumber(checkinForm.pain_level)}));await load();dialog.value='';notify('身体反馈已保存')}catch(e){modalError.value=(e as Error).message}finally{busy.value=false}}
async function saveSchedule(){busy.value=true;modalError.value='';try{const selected=new Set(scheduleForm.value.map(d=>d.date));const all=[...days.value.filter(d=>!selected.has(d.date)),...scheduleForm.value];await api('/availability',json('PUT',{days:all}));await load();dialog.value='';notify('可跑时间已保存')}catch(e){modalError.value=(e as Error).message}finally{busy.value=false}}
async function saveProfile(){busy.value=true;error.value='';try{await api('/profile',json('PATCH',{...profile,age:optionalNumber(profile.age),running_months:optionalNumber(profile.running_months),strength_max_minutes:optionalNumber(profile.strength_max_minutes),goal_duration_seconds:goalMinutes.value?Math.round(goalMinutes.value*60):null,goal_date:profile.goal_date||null,medical_review_date:profile.medical_review_date||null}));await load();notify('个人档案已保存')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function upload(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;busy.value=true;error.value='';try{const body=new FormData();body.append('file',file);const draft=await api<Draft>('/imports',{method:'POST',body});await load();notify(draft.duplicate?'这张截图已经上传，已打开原草稿':'原图已私有保存，请核对并填写数据');editDraft(draft)}catch(e){error.value=(e as Error).message}finally{busy.value=false;if(inputFile.value)inputFile.value.value=''}}
function editDraft(draft:Draft){resetWorkout();const w=draft.fields;Object.assign(workoutForm,{date:w.date||'',started_time:w.started_time||'',sport:w.sport||'',session_context:w.session_context||'unknown',title:w.title||'',distance_km:w.distance_m?w.distance_m/1000:null,duration:w.duration_seconds?duration(w.duration_seconds):'',avg_heart_rate:w.avg_heart_rate??null,max_heart_rate:w.max_heart_rate??null,ascent_m:w.ascent_m??null,effort:w.effort??null,pain_notes:w.pain_notes||'',notes:w.notes||''});selectedDraft.value=draft;draftSaved.value=Boolean(w.date);openDialog('draft')}
async function metricReviewed(updated:Draft){selectedDraft.value=updated;await load();notify('详细指标核对已保存，整次训练仍需单独确认')}
async function refreshRecognition(){if(!selectedDraft.value)return;try{selectedDraft.value=await api<Draft>(`/imports/${selectedDraft.value.id}`);await load()}catch(e){modalError.value=(e as Error).message}}
function applySuggestions(fields:Partial<Workout>){for(const [key,value] of Object.entries(fields)){const target=key==='distance_m'?'distance_km':key==='duration_seconds'?'duration':key;if(!(target in workoutForm))continue;const form=workoutForm as Record<string,unknown>;if(form[target]===null||form[target]==='')form[target]=key==='distance_m'?Number(value)/1000:key==='duration_seconds'?duration(Number(value)):value}draftSaved.value=false;notify('已填入未填写字段，请核对并保存草稿')}
watch(workoutForm,()=>{draftSaved.value=false},{deep:true,flush:'sync'})
async function saveDraft(){if(!selectedDraft.value)return;busy.value=true;modalError.value='';try{selectedDraft.value=await api<Draft>(`/imports/${selectedDraft.value.id}/fields`,json('PATCH',{expected_revision:selectedDraft.value.revision,workout:workoutPayload()}));await load();draftSaved.value=true;notify('草稿已保存，尚未加入训练记录')}catch(e){modalError.value=(e as Error).message}finally{busy.value=false}}
async function confirmDraft(){if(!selectedDraft.value)return;busy.value=true;modalError.value='';try{await api(`/imports/${selectedDraft.value.id}/confirm`,json('POST',{expected_revision:selectedDraft.value.revision}));await load();dialog.value='';notify('确认完成，已加入训练记录')}catch(e){modalError.value=(e as Error).message}finally{busy.value=false}}
function trapFocus(e:KeyboardEvent){if(!dialog.value)return;if(e.key==='Escape')closeDialog();if(e.key==='Tab'){const f=[...modalElement.value!.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled)')];const a=f[0],b=f[f.length-1];if(e.shiftKey&&document.activeElement===a){e.preventDefault();b?.focus()}else if(!e.shiftKey&&document.activeElement===b){e.preventDefault();a?.focus()}}}
onMounted(()=>{initialize();document.addEventListener('keydown',trapFocus)})
onUnmounted(()=>{document.removeEventListener('keydown',trapFocus);clearTimeout(timer)})
</script>

<template>
<div v-if="!ready" class="loading">正在打开你的跑步空间…</div>
<div v-else-if="!user" class="auth-page"><main class="card auth-card"><div class="brand"><i></i>Runner<small>FIND YOUR RHYTHM</small></div><h1>{{initialized?'回到自己的节奏。':'你的跑步空间，从这里开始。'}}</h1><p class="muted tiny">{{initialized?'登录后继续记录训练与身体感受。':'创建本机个人账户，训练数据将保存在这台电脑上。'}}</p><div v-if="error" class="error" role="alert">{{error}}</div><form v-if="initialized||setupAllowed" class="auth-form" @submit.prevent="authenticate"><label class="field">用户名<input v-model="auth.username" autocomplete="username" required maxlength="64" pattern="[\w.\-]+"></label><label class="field">密码<input v-model="auth.password" type="password" :autocomplete="initialized?'current-password':'new-password'" required minlength="8" maxlength="128" placeholder="至少 8 个字符"></label><button class="btn primary" :disabled="busy">{{busy?'正在处理…':initialized?'登录':'创建个人账户'}}</button></form><p v-else class="error">请在服务器本机初始化账户。</p><p class="statusbar">跑步课程 · 记录、评估与确认调整<br>AI 输出需核对；计划确认后生效。</p></main></div>
<template v-else>
<aside><div class="brand"><i></i>Runner<small>FIND YOUR RHYTHM</small></div><nav class="nav" aria-label="主要导航"><button v-for="[id,label,icon] in navs" :key="id" :class="{active:view===id}" @click="changeView(id)"><span class="ico">{{icon}}</span>{{label}}</button></nav><div class="sidefoot"><span class="avatar">{{profile.display_name.slice(0,1)}}</span>{{profile.display_name}}的跑步空间<div class="tiny muted" style="padding-left:44px">每一步，都有方向</div></div></aside>
<div class="shell"><header class="topbar"><div class="crumb">个人训练空间 / {{navs.find(n=>n[0]===view)?.[1]}}</div><div class="topright"><span class="badge">● 个人训练空间</span><span class="tiny muted">{{today}}</span><button class="avatar avatarbutton" aria-label="进入个人设置" @click="changeView('settings')">{{profile.display_name.slice(0,1)}}</button></div></header><div v-if="error" class="error" role="alert">{{error}}</div>
<section v-if="view==='today'"><div class="pagehead"><div><h1>找到自己的节奏。</h1><p class="muted">让计划适应生活，也给身体一点回应的空间。</p></div><button class="btn primary" @click="openDialog('workout')">＋ 记录跑步</button></div><div class="grid"><div class="stack">
<div class="card hero"><HeroArtwork /><div class="hero-content"><div class="eyebrow">TODAY · 今日概览</div><span class="badge">{{healthAttention?'身体状态需要关注':'正在建立训练档案'}}</span><h2>{{healthAttention?'先听听身体的反馈':'每一步，都从了解你开始'}}</h2><p>{{healthAttention?'已记录身体不适。补充今天的感受，后续计划评估会参考这些信息。':'记录训练与身体感受，为后续个性化计划提供依据。'}}</p><button class="btn primary" @click="openDialog('checkin')">更新身体状态 ↗</button></div></div>
<div class="notice"><span style="font-size:19px">◉</span><div><strong>{{healthAttention?'身体反馈已记录':'跑步计划请在下方查看'}}</strong>{{healthAttention?'在计划评估前，保留不适描述与医生建议。':'先完善档案、身体反馈与日程，再核对下方跑步计划。'}}</div><button class="textbtn" style="margin-left:auto;white-space:nowrap" @click="changeView('coach')">教练 →</button></div>
<div class="card"><div class="sectionhead"><h2>这一周，稳稳向前</h2><button class="textbtn" @click="changeView('calendar')">完整日历 ↗</button></div><div class="week"><button v-for="d in week" :key="d.date" class="day" :class="{selected:d.date===today}" @click="changeView('calendar')"><span>周{{d.label}}</span><b>{{d.day}}</b><em>{{d.records.length?'跑步已记录':d.planned.length?'有正式安排':d.availability?.available?'可训练':'未安排'}}</em><div v-if="d.records.length||d.strength.length||d.planned.length||d.availability?.available" class="dot"></div></button></div><div class="weeknote"><span>{{week[0]?.date}} — {{week[6]?.date}}</span><span>跑步 {{thisWeek.length}} 次</span></div></div>
<div class="metrics"><div class="card metric"><span class="tiny muted">本周已跑</span><div class="number">{{weekKm.toFixed(1)}}<small>km</small></div><div class="tiny muted">根据已保存的实际记录</div></div><div class="card metric"><span class="tiny muted">最近一次平均配速</span><div class="number">{{latest?pace(latest.pace_seconds_per_km):'—'}}<small>/km</small></div><div class="tiny muted">{{latest?'由距离和时间计算':'等待第一条记录'}}</div></div><div class="card metric"><span class="tiny muted">累计跑步记录</span><div class="number">{{workouts.length}}<small>次</small></div><div class="tiny muted">持续记录，逐步了解你</div></div></div>
<div class="card"><div class="sectionhead"><h2>最近的一次出发</h2><button class="textbtn" @click="changeView('records')">查看记录 ↗</button></div><div v-if="latest" class="recent"><div class="runicon">↗</div><div><h3>{{latest.title}}</h3><span class="tiny muted">{{latest.date}} {{latest.started_time}} · {{sportLabel(latest.sport)}}</span><div class="recentdata"><div><b>{{(latest.distance_m/1000).toFixed(2)}}</b><span>公里</span></div><div><b>{{duration(latest.duration_seconds)}}</b><span>运动时间</span></div><div><b>{{latest.avg_heart_rate??'—'}}</b><span>平均心率</span></div></div></div></div><div v-else class="empty">还没有训练记录。<br><button class="textbtn" @click="openDialog('workout')">记录第一次出发 →</button></div></div>
</div><div class="stack rightstack"><div class="card goal"><div class="row"><h2>下一站，半程马拉松</h2><span>⚑</span></div><div class="big">{{goalLabel}}<small>目标用时</small></div><p class="tiny muted">{{profile.goal_date||'尚未设置比赛日期'}}<template v-if="daysToGoal!==null"> · {{daysToGoal>=0?`距离比赛 ${daysToGoal} 天`:'比赛日期已过去'}}</template></p><div class="divider"></div><span class="badge">目标可行性待评估</span><p class="tiny muted" style="margin-top:13px">让训练记录和恢复情况，决定接下来的节奏。</p><button class="textbtn" style="margin-top:12px" @click="changeView('settings')">设置我的目标 →</button></div><div class="card"><div class="row"><div class="row"><span class="coachmark">✧</span><h2>教练手记</h2></div><span class="badge">模拟</span></div><p class="quote">好计划也需要留白。<br>先积累真实记录，再决定下一步如何训练。</p><div class="tiny muted">跑步计划可核对确认；真实接口已用合成数据联调，个人方案仍待验收。</div><button class="btn" style="width:100%;margin-top:20px" @click="changeView('coach')">和教练聊聊 ↗</button></div><WeatherCard :refresh-token="refreshToken" :city="profile.city" @calendar="changeView('calendar')"/></div></div><PlanPanel :today="today" :refresh-token="refreshToken" @changed="load"/></section>
<section v-if="view==='calendar'"><div class="pagehead"><div><h1>给训练留出位置。</h1><p class="muted">跑步与恢复共同安排，给恢复留出空间。</p></div><button class="btn" @click="openDialog('schedule')">调整可训练时间</button></div><div class="card panelwide"><div class="sectionhead"><button class="textbtn" @click="weekOffset--">← 上周</button><h2>{{week[0]?.date}} — {{week[6]?.date}}</h2><button class="textbtn" @click="weekOffset++">下周 →</button></div><div class="week"><div v-for="d in week" :key="d.date" class="day" :class="{selected:d.date===today}"><span>周{{d.label}}</span><b>{{d.day}}</b><em>{{d.records.length?'跑步已记录':d.planned.length?'有正式安排':d.availability?.available?'可训练':'未安排'}}</em></div></div><TrainingWeek :dates="week" :days="days" :runs="workouts" :strength="strengthWorkouts" :checkins="checkins" :plan="planState" @feedback="trainingFeedback"/><p class="tiny muted" style="margin-top:20px">可训练时间用于跑步课程，正式安排与实际记录分开保存。</p></div><PlanPanel :today="today" :refresh-token="refreshToken" @changed="load"/></section>
<section v-if="view==='records'"><div class="pagehead"><div><h1>让每次跑步留下线索。</h1><p class="muted">上传原图，核对数据，再告诉教练你的感受。</p></div><button class="btn primary" @click="openDialog('workout')">手工记录</button></div><div class="stack panelwide"><div class="card"><div class="upload"><span style="font-size:30px;color:#78947c">↥</span><h2>从一张运动截图开始</h2><p>原图私有保存 · 选择数据区域 · 分段识别 · 核对确认后保存</p><button class="btn primary" :disabled="busy" @click="inputFile?.click()">{{busy?'上传中…':'选择截图'}}</button><input ref="inputFile" type="file" accept="image/jpeg,image/png,image/webp" hidden @change="upload"></div><template v-if="drafts.length"><div class="sectionhead" style="margin-top:25px"><h2>截图草稿</h2><span class="tiny muted">确认后才进入正式记录</span></div><div v-for="draft in drafts" :key="draft.id" class="calendar-entry row"><div style="min-width:0"><h3 style="overflow-wrap:anywhere">{{draft.original_name}}</h3><span class="tiny muted">{{draft.width}} × {{draft.height}} · {{draft.status==='confirmed'?'已确认':draft.recognition?'已识别 '+draft.recognition.done+'/'+draft.recognition.total+' 段':'待填写核对'}}</span></div><button class="btn" @click="editDraft(draft)">{{draft.status==='confirmed'?'查看':'打开草稿'}}</button></div></template></div><div class="card"><div class="sectionhead"><h2>我的训练记录</h2><span class="tiny muted">{{workouts.length}} 次</span></div><div v-if="!workouts.length" class="empty">还没有记录，上传截图或手工录入即可开始。</div><div v-for="w in workouts" :key="w.id" class="record-entry"><div class="row"><h3>{{w.title}}</h3><span class="badge">{{sportLabel(w.sport)}}</span></div><span class="tiny muted">{{w.date}} {{w.started_time}}</span><div class="recentdata"><div><b>{{(w.distance_m/1000).toFixed(2)}}</b><span>公里</span></div><div><b>{{duration(w.duration_seconds)}}</b><span>运动时间</span></div><div><b>{{pace(w.pace_seconds_per_km)}}</b><span>配速 / km · 计算值</span></div></div><p v-if="w.pain_notes||w.notes" class="tiny muted" style="margin-top:15px">{{w.pain_notes}} {{w.notes}}</p><WorkoutMetrics :workout="w"/></div></div></div><WeatherCard :refresh-token="refreshToken" :city="profile.city" @calendar="changeView('calendar')"/><FeedbackHistory :checkins="checkins" :runs="workouts" :strength="strengthWorkouts" :timezone="profile.timezone"/></section>
<section v-if="view==='coach'"><div class="pagehead"><div><h1>聊聊今天的你。</h1><p class="muted">把生活里的变化，也放进训练计划。</p></div></div><AssessmentPanel :today="today" :refresh-token="refreshToken" @navigate="changeView" @feedback="openDialog('checkin')"/><CyclePanel :today="today" :refresh-token="refreshToken" @changed="load"/><CoachChat :refresh-token="refreshToken" @feedback="openDialog('checkin')"/><PlanPanel :today="today" :refresh-token="refreshToken" @changed="load"/></section>
<section v-if="view==='settings'"><div class="pagehead"><div><h1>按你的方式来。</h1><p class="muted">训练目标、生活日程和身体情况，都由你决定。</p></div><button class="btn" :disabled="busy" @click="logout">退出登录</button></div><form class="card panelwide" @submit.prevent="saveProfile"><h2>我的档案</h2><div class="form-grid" style="margin-top:25px"><label class="field">称呼<input v-model="profile.display_name" required maxlength="40"></label><label class="field">年龄<input v-model.number="profile.age" type="number" min="1" max="120"></label><label class="field">性别<select v-model="profile.sex"><option value="unspecified">暂不填写</option><option value="male">男</option><option value="female">女</option></select></label><label class="field">跑龄 / 月<input v-model.number="profile.running_months" type="number" min="0" max="1200"></label><label class="field">每周训练次数<input v-model.number="profile.runs_per_week" type="number" min="1" max="7" required></label><label class="field">跑步城市<input v-model="profile.city" placeholder="选择你实际跑步的城市" maxlength="80"></label><label class="field">常用跑步时段<input v-model="profile.preferred_time" type="time" required></label><label class="field">时区<input v-model="profile.timezone" required></label><label class="field">半马比赛日期<input v-model="profile.goal_date" type="date"></label><label class="field">半马目标用时 / 分钟<input v-model.number="goalMinutes" type="number" min="30" max="1440" step="0.5" placeholder="例如：110"></label><label class="field span2">伤痛与身体情况<textarea v-model="profile.health_notes" maxlength="2000" placeholder="位置、出现时机、持续情况"></textarea></label><label class="field">医生建议的个人记录<select v-model="profile.running_permission"><option value="unknown">未知 / 尚未评估</option><option value="user_reports_doctor_allows">我已就诊，医生允许继续跑步</option></select></label><label class="field">就诊评估日期（未知留空）<input v-model="profile.medical_review_date" type="date" :max="today"></label><p class="tiny muted span2">这是个人自述，不是系统医学认证；新疼痛、疾病及医生限制仍优先影响安排。</p><label class="field span2">医生给出的运动限制<textarea v-model="profile.doctor_restrictions" maxlength="2000" placeholder="没有得到建议可以暂时留空"></textarea></label></div><div class="settingsrow"><div><h3>微信与天气提醒</h3><p class="tiny muted">本地提醒配置与天气见下方；微信未接通</p></div><span class="badge">尚未启用</span></div><div class="settingsrow"><div><h3>计划变更需我确认</h3><p class="tiny muted">后续每次变更先看依据和前后对比</p></div><span class="badge">始终启用</span></div><div class="actions"><button class="btn primary" :disabled="busy">{{busy?'保存中…':'保存个人档案'}}</button></div></form><NotificationPanel :refresh-token="refreshToken"/><DataExportPanel/><DataDeletionPanel @changed="load"/><WeatherCard :refresh-token="refreshToken" :city="profile.city" @calendar="changeView('calendar')"/><FeedbackHistory :checkins="checkins" :runs="workouts" :strength="strengthWorkouts" :timezone="profile.timezone"/></section>
<div class="screen-note">RUNNER · 每一步，都有方向 / 数据保存在本机 · {{aiUsage?.provider==='deepseek'?'截图识别已配置 DeepSeek':'截图识别未启用'}}</div></div>
<nav class="bottom" aria-label="手机导航"><button v-for="[id,label,icon] in navs" :key="id" :class="{active:view===id}" @click="changeView(id)"><span class="ico">{{icon}}</span>{{label.replace('今日概览','今日').replace('训练','').replace('个人','')}}</button></nav>
<div v-if="dialog" class="modal-wrap open" @click.self="closeDialog"><section ref="modalElement" class="modal" role="dialog" aria-modal="true" aria-labelledby="dialogtitle"><div class="row"><h2 id="dialogtitle">{{dialog==='workout'?'记录这次出发':dialog==='checkin'?'今天，身体感觉怎么样？':dialog==='schedule'?'安排你的训练时间':'核对截图草稿'}}</h2><button class="textbtn" aria-label="关闭弹窗" :disabled="busy" @click="closeDialog">✕</button></div><div v-if="modalError" class="error" role="alert">{{modalError}}</div>
<template v-if="dialog==='workout'||dialog==='draft'"><template v-if="dialog==='draft'&&selectedDraft"><p class="evidence-note">{{selectedDraft.status==='confirmed'?'这张截图已确认并生成训练记录。':'原图已私有保存。识别结果是待核对草稿，确认前不会加入训练记录。'}}</p><a :href="selectedDraft.image_url" target="_blank" rel="noopener">打开完整原图 ↗</a><details class="original-thumbnail"><summary>查看完整图片缩略图</summary><img class="field-preview" :src="selectedDraft.image_url" alt="本次上传的运动截图"></details><ImportRecognition :key="selectedDraft.id" :draft="selectedDraft" :disabled="selectedDraft.status==='confirmed'" @suggestions="applySuggestions" @refresh="refreshRecognition" @reviewed="metricReviewed" @working="busy=$event"/><p v-if="selectedDraft.possible_duplicate_ids.length" class="evidence-note">已有 {{selectedDraft.possible_duplicate_ids.length}} 条日期、距离和时长相近的记录，请检查是否重复导入。</p></template><form @submit.prevent="dialog==='workout'?saveWorkout():saveDraft()"><fieldset :disabled="busy||(dialog==='draft'&&selectedDraft?.status==='confirmed')" style="border:0;padding:0;margin:0"><div class="form-grid"><label class="field">运动日期<input v-model="workoutForm.date" aria-label="运动日期" :class="{'required-empty':workoutMissing('date')}" :aria-invalid="workoutMissing('date')?'true':undefined" :aria-describedby="workoutMissing('date')?'required-date':undefined" type="date" required><span v-if="workoutMissing('date')" id="required-date" class="required-message" aria-hidden="true">必填，请填写运动日期</span></label><label class="field">开始时间（可选）<input v-model="workoutForm.started_time" type="time"></label><label class="field">运动类型<select v-model="workoutForm.sport" aria-label="运动类型" :class="{'required-empty':workoutMissing('sport')}" :aria-invalid="workoutMissing('sport')?'true':undefined" :aria-describedby="workoutMissing('sport')?'required-sport':undefined" required><option disabled value="">请选择运动类型</option><option value="road_run">户外跑</option><option value="trail_run">越野跑</option><option value="treadmill">跑步机</option></select><span v-if="workoutMissing('sport')" id="required-sport" class="required-message" aria-hidden="true">必填，请填写运动类型</span></label><label class="field">记录性质（由你核对）<select v-model="workoutForm.session_context"><option value="unknown">未知 / 未标记</option><option value="easy">轻松跑</option><option value="long">较长跑</option><option value="steady">稳态训练</option><option value="race">实际比赛</option></select></label><label class="field">训练名称<input v-model="workoutForm.title" aria-label="训练名称" :class="{'required-empty':workoutMissing('title')}" :aria-invalid="workoutMissing('title')?'true':undefined" :aria-describedby="workoutMissing('title')?'required-title':undefined" required maxlength="100"><span v-if="workoutMissing('title')" id="required-title" class="required-message" aria-hidden="true">必填，请填写训练名称</span></label><label class="field">实际距离 / km<input v-model.number="workoutForm.distance_km" aria-label="实际距离 / km" :class="{'required-empty':workoutMissing('distance_km')}" :aria-invalid="workoutMissing('distance_km')?'true':undefined" :aria-describedby="workoutMissing('distance_km')?'required-distance_km':undefined" inputmode="decimal" type="number" step="0.001" min="0.001" max="500" required><span v-if="workoutMissing('distance_km')" id="required-distance_km" class="required-message" aria-hidden="true">必填，请填写实际距离 / km</span></label><label class="field">运动时间<input v-model="workoutForm.duration" aria-label="运动时间" :class="{'required-empty':workoutMissing('duration')}" :aria-invalid="workoutMissing('duration')?'true':undefined" :aria-describedby="workoutMissing('duration')?'required-duration':undefined" placeholder="01:03:54 或 35:20" required><span v-if="workoutMissing('duration')" id="required-duration" class="required-message" aria-hidden="true">必填，请填写运动时间</span></label><label class="field">平均心率（可选）<input v-model.number="workoutForm.avg_heart_rate" type="number" min="30" max="250"></label><label class="field">最大心率（可选）<input v-model.number="workoutForm.max_heart_rate" type="number" min="30" max="250"></label><label class="field">累计爬升 / m（可选）<input v-model.number="workoutForm.ascent_m" type="number" min="0" max="30000" step="0.1"></label><label class="field">用力程度 / 10（可选）<input v-model.number="workoutForm.effort" type="number" min="0" max="10"></label><label class="field span2">跑中或跑后不适<textarea v-model="workoutForm.pain_notes" maxlength="2000" placeholder="没有不适可以留空"></textarea></label><label class="field span2">其他备注<textarea v-model="workoutForm.notes" maxlength="2000"></textarea></label></div></fieldset><p v-if="missingWorkoutFields.length" class="required-message" role="status">请补齐必填项：{{missingWorkoutFields.join('、')}}。</p><p v-else-if="dialog==='draft'&&!draftSaved&&selectedDraft?.status!=='confirmed'" class="tiny muted" role="status">必填项已填写，请先保存核对草稿，再确认加入训练记录。</p><div v-if="selectedDraft?.status!=='confirmed'||dialog==='workout'" class="actions"><button class="btn" :disabled="busy">{{busy?'保存中…':dialog==='workout'?'保存训练':'保存核对草稿'}}</button><button v-if="dialog==='draft'" type="button" class="btn primary" :disabled="busy||!draftSaved||missingWorkoutFields.length>0" @click="confirmDraft">确认加入训练记录</button></div></form></template>
<form v-if="dialog==='checkin'" @submit.prevent="saveCheckin"><div class="form-grid"><label class="field">日期<input v-model="checkinForm.date" type="date" required></label><label class="field">反馈发生时间（可选）<input v-model="feedbackClock" type="time"><span class="tiny muted">使用档案时区 {{profile.timezone}}；不清楚可留空。</span></label><label class="field">反馈时机<select v-model="checkinForm.feedback_phase"><option value="unknown">时机未确定</option><option value="before">训练前</option><option value="during">训练中</option><option value="after">训练后</option><option value="next_day">次日</option></select></label><label class="field span2">关联实际训练（可选）<select v-model="feedbackTraining"><option value="">不关联某次训练</option><option v-for="r in feedbackOptions" :key="r.key" :value="r.key">{{r.date}} · {{r.type==='run'?'跑步':'力量'}} · {{r.title}}</option></select></label><label class="field">睡眠时长 / 小时（可选）<input v-model.number="checkinForm.sleep_hours" type="number" min="0" max="24" step="0.5"></label><label class="field span2">整体疲劳 {{checkinForm.fatigue}} / 10<input v-model.number="checkinForm.fatigue" class="range" type="range" min="0" max="10"></label><label class="field">今天的训练意愿<select v-model="checkinForm.training_readiness"><option value="unknown">尚不确定，需要评估</option><option value="ready">感觉可按常规安排（仍需检查不适）</option><option value="reduce">希望缩短或降低负荷</option><option value="rest">今天希望休息</option></select></label><label class="field">肌肉酸胀程度 / 10（可选）<input v-model.number="checkinForm.soreness_level" type="number" min="0" max="10" placeholder="明确没有填 0"></label><label class="field">酸胀部位<input v-model="checkinForm.soreness_location" maxlength="100"></label><label class="field">酸胀出现时机<select v-model="checkinForm.soreness_timing"><option value="unknown">不确定 / 未填写</option><option value="none">没有酸胀</option><option value="during">训练中</option><option value="after">训练后</option><option value="next_day">次日</option></select></label><label class="field">酸胀变化<select v-model="checkinForm.soreness_trend"><option value="unknown">未确定</option><option value="improving">在减轻</option><option value="stable">差不多</option><option value="worsening">在加重</option></select></label><label class="field">酸胀时的轻松活动耐受（自述）<select v-model="checkinForm.soreness_tolerability"><option value="unknown">不确定 / 尚未核对</option><option value="tolerable">感觉可耐受轻松活动</option><option value="not_tolerable">不适合继续活动</option></select><span class="tiny muted">不等于医学许可；疼痛、加重或活动受影响仍须暂停核对。</span></label><label class="field">走路、上下楼或动作是否受影响<select v-model="checkinForm.function_affected"><option :value="null">不确定 / 未填写</option><option :value="false">没有受影响</option><option :value="true">有影响</option></select></label><label class="field span2">生病或其他身体变化<textarea v-model="checkinForm.illness_notes" maxlength="1000"></textarea></label><label class="field">疼痛部位（可选）<input v-model="checkinForm.pain_location" maxlength="100" placeholder="例如：左膝内侧（与肌肉酸胀分开）"></label><label class="field">疼痛程度 / 10（可选）<input v-model.number="checkinForm.pain_level" type="number" min="0" max="10"></label><label class="field">出现时机<select v-model="checkinForm.pain_timing"><option value="none">没有不适</option><option value="during">训练中</option><option value="after">训练后</option><option value="daily">平时也有</option><option value="unknown">不确定</option></select></label><label class="field span2">补充描述<textarea v-model="checkinForm.notes" maxlength="2000"></textarea></label></div><div class="actions"><button class="btn primary" :disabled="busy">保存身体反馈</button></div></form>
<form v-if="dialog==='schedule'" @submit.prevent="saveSchedule"><p>勾选可训练日期，填写跑步可用的时长。</p><div v-for="d in scheduleForm" :key="d.date" class="settingsrow"><label><input v-model="d.available" type="checkbox"> {{d.date}}</label><label class="field" style="max-width:140px">可用时长 / 分钟<input v-model.number="d.duration_minutes" type="number" min="10" max="480" required :disabled="!d.available"></label></div><div class="actions"><button class="btn primary" :disabled="busy">保存可训练时间</button></div></form>
</section></div>
</template><div v-if="toastText" class="toast" style="display:block" role="status">{{toastText}}</div>
</template>

<style scoped>
.field .required-empty{border:1.5px solid #b53c32;background:#fff8f6}.field .required-empty:focus{outline:2px solid #b53c32;outline-offset:2px}.required-message{color:#a3332b;font-size:12px;line-height:1.6;margin-top:6px}
</style>
